import { EChartsType } from '@/src/echarts';
import { createChart, getECModel } from '../../../core/utHelper';
import { SankeySeriesOption } from '@/src/chart/sankey/SankeySeries';

type RectLikeEl = {
    shape: {
        r?: number | number[]
    }
};

function makeOption(itemStyle?: SankeySeriesOption['itemStyle']) {
    return {
        animation: false,
        series: [{
            type: 'sankey' as const,
            itemStyle: itemStyle,
            data: [{
                name: 'a'
            }, {
                name: 'b'
            }, {
                name: 'c',
                itemStyle: {
                    borderRadius: [1, 2, 3, 4]
                }
            }],
            links: [{
                source: 'a',
                target: 'b',
                value: 5
            }, {
                source: 'b',
                target: 'c',
                value: 3
            }]
        }]
    };
}

function getNodeRects(chart: EChartsType): RectLikeEl[] {
    const seriesModel = getECModel(chart).getSeriesByIndex(0);
    const els: RectLikeEl[] = [];
    seriesModel.getData().eachItemGraphicEl(function (el) {
        els.push(el as unknown as RectLikeEl);
    });
    return els;
}

describe('sankey_borderRadius', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should keep sharp corners when itemStyle.borderRadius is not set', function () {
        chart.setOption(makeOption());
        const rects = getNodeRects(chart);
        expect(rects.length).toBe(3);
        // Node 'c' declares its own borderRadius.
        expect(rects[0].shape.r).toBe(0);
        expect(rects[1].shape.r).toBe(0);
    });

    it('should apply a number itemStyle.borderRadius on every node', function () {
        chart.setOption(makeOption({ borderRadius: 6 }));
        const rects = getNodeRects(chart);
        expect(rects.length).toBe(3);
        expect(rects[0].shape.r).toBe(6);
        expect(rects[1].shape.r).toBe(6);
    });

    it('should apply an array itemStyle.borderRadius', function () {
        chart.setOption(makeOption({ borderRadius: [10, 8, 6, 4] }));
        const rects = getNodeRects(chart);
        expect(rects[0].shape.r).toEqual([10, 8, 6, 4]);
    });

    it('should support per-data-item itemStyle.borderRadius overriding the series one', function () {
        chart.setOption(makeOption({ borderRadius: 6 }));
        const rects = getNodeRects(chart);
        expect(rects[2].shape.r).toEqual([1, 2, 3, 4]);
    });
});

