}];

describe('sankey_undefined_options', function () {

    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should not throw when links is undefined', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: nodes,
                    links: undefined
                }]
            });
        }).not.toThrow();
    });

    it('should not throw when edges is undefined', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    nodes: nodes,
                    edges: undefined
                }]
            });
        }).not.toThrow();
    });

    it('should not throw when data / nodes is undefined', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: undefined,
                    links: links
                }]
            });
        }).not.toThrow();
    });

    it('should not throw when levels is undefined', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    levels: undefined,
                    data: nodes,
                    links: links
                }]
            });
        }).not.toThrow();
    });

    it('should not throw when links / nodes / levels are all undefined', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: undefined,
                    nodes: undefined,
                    links: undefined,
                    edges: undefined,
                    levels: undefined
                }]
            });
        }).not.toThrow();
    });

    it('should still render normally when the arrays are provided', function () {
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: nodes,
                    links: links,
                    levels: [{
                        depth: 0,
                        itemStyle: {
                            color: '#ff0000'
                        }
                    }]
                }]
            });
        }).not.toThrow();

        const seriesModel = getECModel(chart).getSeriesByIndex(0);
        expect(seriesModel.getData().count()).toBe(3);
        expect(seriesModel.getData('edge').count()).toBe(2);

        let elCount = 0;
        seriesModel.getData().eachItemGraphicEl(function () {
            elCount++;
        });
        expect(elCount).toBe(3);
    });
});

